#[test] fn non_msgsend_refused() {
    assert!(Send::decode_tx_raw(&b64d(""), "x", 0).is_err(), "ibc_transfer");
    assert!(Send::decode_tx_raw(&b64d(""), "x", 0).is_err(), "msg_vote");
    assert!(Send::decode_tx_raw(&b64d(""), "x", 0).is_err(), "terra_wasm");
    assert!(Send::decode_tx_raw(&b64d(""), "x", 0).is_err(), "stargaze_cw721");
}
